            <div className="flex flex-wrap gap-8">
              <MetaBlock label="Written by">
                <div className="flex items-center gap-2">
                  <AvatarChip article={article} />
                  <span>{article.author.name}</span>
                </div>
              </MetaBlock>
              <MetaBlock label="Published on">
